def algorithm(func, dim, lb, ub, budget, rng):
    best_solution = None
    best_value = float('inf')

    for _ in range(budget):
        candidate = np.array([rng.uniform(lb, ub) for _ in range(dim)])
        value = func(candidate)

        if value < best_value:
            best_value = value
            best_solution = candidate

    return best_solution
